{
  "predictors": [
    {
      "name": "R&D Intensity Momentum",
      "construction": "Calculate the change in R&D expenditure (Compustat item XRD) as a percentage of total assets (Compustat item AT) over the past 3 years.",
      "rationale": "Firms increasing their R&D intensity might be investing in future growth and innovation, which can lead to superior performance.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Supplier Concentration Risk",
      "construction": "Measure the concentration of suppliers from 10-K filings by identifying the number of key suppliers and their share of total procurement costs.",
      "rationale": "Firms dependent on fewer suppliers might face operational risks, impacting expected returns.",
      "higher_returns_for": "Low values of the measure"
    },
    {
      "name": "Employee Growth Rate",
      "construction": "Calculate the annual growth rate in employee numbers from company reports available in 10-K filings over the last 5 years.",
      "rationale": "Rapid employee growth might signal expansion and future earnings potential.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Green Technology Investment",
      "construction": "Quantify the capital expenditures aimed at green technologies as reported in the 10-K sustainability disclosures.",
      "rationale": "Investments in sustainable technology might align with regulatory trends and consumer preferences, boosting future returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Board Independence Ratio",
      "construction": "Calculate the ratio of independent directors to total board members using data from company proxy statements (DEF 14A).",
      "rationale": "A higher proportion of independent directors can lead to better governance and decision-making.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Customer Sentiment Index",
      "construction": "Construct an index based on sentiment analysis of customer reviews and feedback from online platforms, averaged over the past year.",
      "rationale": "Positive customer sentiment may translate to better future sales and profitability.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Patent Citation Impact",
      "construction": "Measure the number of citations per patent, using data from the US Patent and Trademark Office over the past 5 years.",
      "rationale": "Patents with higher citations may indicate valuable innovations with significant market impact.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Insider Trading Momentum",
      "construction": "Track the net number of shares bought by insiders (from SEC Form 4 filings) over the past 6 months.",
      "rationale": "Increased insider buying may reflect management's confidence in future firm performance.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Brand Value Growth",
      "construction": "Estimate brand value growth by comparing advertising expenditure (SG&A from Compustat) against sales growth, over the past 3 years.",
      "rationale": "Investments in brand can lead to higher pricing power and customer loyalty, predicting future returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Foreign Revenue Exposure",
      "construction": "Calculate the percentage of total revenue derived from foreign operations, using segments data in 10-K filings.",
      "rationale": "Firms with higher foreign revenue may benefit from global diversification and emerging market growth.",
      "higher_returns_for": "High values of the measure"
    }
  ]
}
